CREATE TABLE IF NOT EXISTS ops_technicians (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','inactive')), skills_json JSONB NOT NULL, districts_json JSONB NOT NULL, shift_start TEXT NOT NULL, shift_end TEXT NOT NULL, max_daily_minutes INTEGER NOT NULL CHECK (max_daily_minutes BETWEEN 60 AND 960), created_by TEXT NOT NULL, updated_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS ops_workforce_assignments (target_type TEXT NOT NULL, target_id TEXT NOT NULL, technician_id TEXT NOT NULL REFERENCES ops_technicians(id) ON UPDATE CASCADE ON DELETE RESTRICT, client_id TEXT NOT NULL, wall_id TEXT NOT NULL, service_date DATE NOT NULL, scheduled_start TIMESTAMPTZ, estimated_minutes INTEGER NOT NULL CHECK (estimated_minutes BETWEEN 15 AND 480), required_skills_json JSONB NOT NULL, district TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('planned','accepted','in_progress','completed','cancelled')), assigned_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(target_type,target_id));
CREATE INDEX IF NOT EXISTS idx_pg_workforce_technician_date ON ops_workforce_assignments(technician_id, service_date, status);
CREATE INDEX IF NOT EXISTS idx_pg_workforce_client_date ON ops_workforce_assignments(client_id, service_date, status);
CREATE INDEX IF NOT EXISTS idx_pg_workforce_schedule ON ops_workforce_assignments(technician_id, scheduled_start);
INSERT INTO schema_migrations(version, applied_at) VALUES ('2026-08-30.postgres-workforce-dispatch-v1', NOW()) ON CONFLICT(version) DO NOTHING;
